from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if abs(k) > total:
            return -1

        offset = total
        target_bit = 1 << (k + offset)

        zero_ok = False
        if 0 in nums:
            # st[0]: even length, no zero selected
            # st[1]: odd length, no zero selected
            # st[2]: even length, zero selected
            # st[3]: odd length, zero selected
            st = [1 << offset, 0, 0, 0]
            for x in nums:
                old = st[:]
                if x > 0:
                    st[1] |= old[0] << x
                    st[0] |= old[1] >> x
                    st[3] |= old[2] << x
                    st[2] |= old[3] >> x
                else:
                    st[3] |= old[0] | old[2]
                    st[2] |= old[1] | old[3]
            zero_ok = bool((st[2] | st[3]) & target_bit)

        dp0 = [0] * (limit + 1)
        dp1 = [0] * (limit + 1)

        for x in nums:
            if x == 0 or x > limit:
                continue

            old0 = dp0[:]
            old1 = dp1[:]

            dp1[x] |= 1 << (x + offset)

            for p in range(1, limit // x + 1):
                q = p * x
                if old0[p]:
                    dp1[q] |= old0[p] << x
                if old1[p]:
                    dp0[q] |= old1[p] >> x

        for p in range(limit, 0, -1):
            if (dp0[p] | dp1[p]) & target_bit:
                return p

        return 0 if zero_ok else -1

import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    s = data[1]
    t = data[2]

    target = [-1] * 26

    for cs, ct in zip(s, t):
        c = ord(cs) - 97
        d = ord(ct) - 97
        if target[c] == -1:
            target[c] = d
        elif target[c] != d:
            print(-1)
            return

    present = [False] * 26
    appearing = []
    for c in range(26):
        if target[c] != -1:
            present[c] = True
            appearing.append(c)

    mandatory = 0
    for c in appearing:
        if target[c] != c:
            mandatory += 1

    indeg = [0] * 26
    for c in appearing:
        d = target[c]
        if present[d]:
            indeg[d] += 1

    state = [0] * 26
    pure_cycles = 0

    for c in appearing:
        if state[c] != 0:
            continue

        path = []
        pos = {}
        u = c

        while u is not None and state[u] == 0:
            state[u] = 1
            pos[u] = len(path)
            path.append(u)
            d = target[u]
            u = d if present[d] else None

        if u is not None and state[u] == 1 and u in pos:
            cycle = path[pos[u]:]
            if len(cycle) >= 2 and all(indeg[v] == 1 for v in cycle):
                pure_cycles += 1

        for v in path:
            state[v] = 2

    if pure_cycles > 0 and len(appearing) == 26 and all(indeg[c] == 1 for c in appearing):
        print(-1)
    else:
        print(mandatory + pure_cycles)

if __name__ == "__main__":
    solve()

import sys
from bisect import bisect_left


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N]
    B = data[1 + N:1 + 2 * N]

    ca = {}
    cb = {}
    max_known = 0
    k = 0
    m = 0

    for x in A:
        if x >= 0:
            k += 1
            ca[x] = ca.get(x, 0) + 1
            if x > max_known:
                max_known = x

    for x in B:
        if x >= 0:
            m += 1
            cb[x] = cb.get(x, 0) + 1
            if x > max_known:
                max_known = x

    del data, A, B

    L = k + m - N
    out = sys.stdout.write

    if L <= 1:
        out("Yes\n")
        return

    items_a = list(ca.items())
    items_b = list(cb.items())
    del ca, cb

    # Use the smaller distinct-value list as the outer loop.
    if len(items_a) <= len(items_b):
        outer = items_a
        inner = items_b
    else:
        outer = items_b
        inner = items_a

    inner.sort()
    inner_len = len(inner)
    inner_vals = [v for v, _ in inner]
    all_inner_one = all(c == 1 for _, c in inner)

    sums = []
    append = sums.append
    extend = sums.extend
    need = L
    max_s = max_known
    bl = bisect_left

    for x, cnt_x in outer:
        # Keep only y such that x + y >= max_known.
        idx = bl(inner_vals, max_s - x)
        if idx == inner_len:
            continue

        # If cnt_x == 1 or every inner count is 1, every pair in this chunk
        # has multiplicity exactly 1.
        if cnt_x == 1 or all_inner_one:
            if idx == 0:
                extend([x + y for y in inner_vals])
            else:
                extend([x + y for y in inner_vals[idx:]])
        else:
            if idx == 0:
                iterable = inner
            else:
                iterable = inner[idx:]

            for y, cnt_y in iterable:
                s = x + y
                w = cnt_x if cnt_x < cnt_y else cnt_y

                # One value pair alone already provides enough known-known pairs.
                if w >= need:
                    out("Yes\n")
                    return

                if w == 1:
                    append(s)
                else:
                    extend([s] * w)

    if len(sums) < need:
        out("No\n")
        return

    sums.sort()

    it = iter(sums)
    prev = next(it)
    cnt = 1
    for x in it:
        if x == prev:
            cnt += 1
            if cnt >= need:
                out("Yes\n")
                return
        else:
            prev = x
            cnt = 1

    out("No\n")


if __name__ == "__main__":
    main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    t = int(data[0])
    idx = 1
    out = []
    append = out.append
    SHIFT = 10**6

    for _ in range(t):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2

        if R == 2 and B == 3:
            append("Yes")
            append("B 2 3")
            append("R 3 2 ")
            append("B 2 2")
            append("B 3 3")
            append("R 2 4")
            continue

        if R + B < 2 or (R & 1) or (R == 0 and (B & 1)):
            append("No")
            continue

        append("Yes")

        if R > 0 and B > 0:
            m = R // 2 - 1

            # Red snake: (0,0), (0,-1), ..., (0,-m), (1,-m), ..., (1,0)
            for c in range(0, -m - 1, -1):
                append(f"R {SHIFT} {SHIFT + c}")
            for c in range(-m, 1):
                append(f"R {SHIFT + 1} {SHIFT + c}")

            if B & 1:
                # B = 2L + 1
                L = B // 2
                append(f"B {SHIFT + 1} {SHIFT + 1}")
                for k in range(1, L + 1):
                    append(f"B {SHIFT + 1 - k} {SHIFT + 1 + k}")
                for k in range(L, 0, -1):
                    append(f"B {SHIFT - k} {SHIFT + k}")
            else:
                # B = 2L + 2
                L = B // 2 - 1
                append(f"B {SHIFT + 2} {SHIFT}")
                for k in range(0, L + 1):
                    append(f"B {SHIFT + 1 - k} {SHIFT + 1 + k}")
                for k in range(L, 0, -1):
                    append(f"B {SHIFT - k} {SHIFT + k}")

        elif B == 0:
            # All red: 1-based 2 x (R/2) perimeter starting at (1,1)
            K = R // 2
            for c in range(1, K + 1):
                append(f"R 1 {c}")
            for c in range(K, 0, -1):
                append(f"R 2 {c}")

        else:
            # All blue: 2 x (B/2) perimeter in (a,b), mapped to (r,c)=(a+b,a-b)
            K = B // 2
            for b in range(K):
                append(f"B {SHIFT + b} {SHIFT - b}")
            for b in range(K - 1, -1, -1):
                append(f"B {SHIFT + 1 + b} {SHIFT + 1 - b}")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        max_r = 0
        for _, r in queries:
            if r > max_r:
                max_r = r

        powers = []
        p = 1
        while p <= max_r:
            powers.append(p)
            p *= 4

        def prefix(n: int) -> int:
            if n <= 0:
                return 0
            total = 0
            for p in powers:
                if p > n:
                    break
                total += n - p + 1
            return total

        ans = 0
        for l, r in queries:
            d = prefix(r) - prefix(l - 1)
            ans += (d + 1) // 2
        return ans

import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    adj = [[] for _ in range(N)]

    idx = 2
    for _ in range(M):
        u = data[idx] - 1
        v = data[idx + 1] - 1
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    m = M & 1

    # For odd N, every maximal final complete bipartite graph has an even
    # number of edges, so the parity of the total number of moves is M mod 2.
    if N & 1:
        print("Aoki" if m else "Takahashi")
        return

    color = [-1] * N
    odd_components = 0
    isolated = 0
    b = 0  # parity of components whose two bipartition sides are both odd

    for start in range(N):
        if color[start] != -1:
            continue

        color[start] = 0
        stack = [start]
        c0 = 1
        c1 = 0

        while stack:
            x = stack.pop()
            nxt_color = color[x] ^ 1
            for y in adj[x]:
                if color[y] == -1:
                    color[y] = nxt_color
                    if nxt_color == 0:
                        c0 += 1
                    else:
                        c1 += 1
                    stack.append(y)

        size = c0 + c1
        if size & 1:
            odd_components += 1
            if size == 1:
                isolated += 1
        else:
            if (c0 & 1) and (c1 & 1):
                b ^= 1

    if isolated == odd_components:
        first_loses = (m == (b ^ ((odd_components // 2) & 1)))
    elif isolated >= odd_components - 2:
        first_loses = False
    else:
        first_loses = (m == 0)

    print("Takahashi" if first_loses else "Aoki")


if __name__ == "__main__":
    main()

import sys


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n: int) -> int:
            if n <= 0:
                return 0

            bound = str(n)
            L = len(bound)

            fact = [1] * (L + 1)
            for i in range(1, L + 1):
                fact[i] = fact[i - 1] * i

            powers = [[1] * (L + 1) for _ in range(10)]
            for d in range(1, 10):
                for c in range(1, L + 1):
                    powers[d][c] = powers[d][c - 1] * d

            def count_leq(counts, initial_denom):
                rem = counts[:]
                cur_denom = initial_denom
                ans = 0
                total = L

                for i, ch in enumerate(bound):
                    limit = ord(ch) - 48
                    rem_total = total - i

                    # Put a smaller non-zero digit here.
                    for d in range(1, limit):
                        c = rem[d]
                        if c:
                            ans += fact[rem_total - 1] * c // cur_denom

                    # Continue with the equal digit if possible.
                    if 1 <= limit <= 9:
                        c = rem[limit]
                        if c:
                            cur_denom //= c
                            rem[limit] = c - 1
                            continue

                    return ans

                return ans + 1

            counts = [0] * 10
            bad = 0

            def dfs(idx, remaining, length, digit_sum, product, denom):
                nonlocal bad

                if idx == 9:
                    if length > 0 and product % digit_sum != 0:
                        if length < L:
                            bad += fact[length] // denom
                        else:
                            bad += count_leq(counts, denom)
                    return

                d = idx + 1
                for c in range(remaining + 1):
                    counts[d] = c
                    dfs(
                        idx + 1,
                        remaining - c,
                        length + c,
                        digit_sum + c * d,
                        product * powers[d][c],
                        denom * fact[c],
                    )
                counts[d] = 0

            dfs(0, L, 0, 0, 1, 1)
            return n - bad

        return count_upto(r) - count_upto(l - 1)


def is_beautiful(x: int) -> bool:
    s = 0
    p = 1
    while x > 0:
        d = x % 10
        s += d
        p *= d
        x //= 10
    return p % s == 0


def run_checks() -> bool:
    sol = Solution()
    failures = []

    def check(name, actual, expected):
        if actual != expected:
            failures.append(f"{name}: actual={actual} expected={expected}")

    check("example1", sol.beautifulNumbers(10, 20), 2)
    check("example2", sol.beautifulNumbers(1, 15), 10)
    check("edge_1", sol.beautifulNumbers(1, 1), 1)
    check("edge_11", sol.beautifulNumbers(11, 11), 0)
    check("edge_10_20", sol.beautifulNumbers(10, 20), 2)
    check("edge_1_15", sol.beautifulNumbers(1, 15), 10)

    large = 999999999
    check("edge_large", sol.beautifulNumbers(large, large), 1 if is_beautiful(large) else 0)

    N = 2000
    brute_pref = [0] * (N + 1)
    for x in range(1, N + 1):
        y = x
        s = 0
        p = 1
        while y > 0:
            d = y % 10
            s += d
            p *= d
            y //= 10
        brute_pref[x] = brute_pref[x - 1] + (1 if p % s == 0 else 0)

    sol_pref = [0] * (N + 1)
    bn = sol.beautifulNumbers
    for n in range(1, N + 1):
        sol_pref[n] = bn(1, n)

    for n in range(1, N + 1):
        if sol_pref[n] != brute_pref[n]:
            failures.append(f"prefix n={n}: sol={sol_pref[n]} brute={brute_pref[n]}")
            break

    if not failures:
        M = 50
        for l in range(1, M + 1):
            for r in range(l, M + 1):
                expected = brute_pref[r] - brute_pref[l - 1]
                actual = bn(l, r)
                if actual != expected:
                    failures.append(f"direct l={l} r={r}: sol={actual} brute={expected}")
                    break
            if failures:
                break

    if not failures:
        sp = sol_pref
        bp = brute_pref
        expected_total = N * (N + 1) // 2

        for l in range(1, N + 1):
            sol_l = sp[l - 1]
            brute_l = bp[l - 1]
            for r in range(l, N + 1):
                if sp[r] - sol_l != bp[r] - brute_l:
                    failures.append(
                        f"range l={l} r={r}: sol={sp[r] - sol_l} brute={bp[r] - brute_l}"
                    )
                    break
            if failures:
                break

        if not failures:
            print("examples and edge cases: pass")
            print("direct small ranges 1..50: pass")
            print(f"all range differences 1..2000: pass ({expected_total}/{expected_total})")
            print("overall: pass")
            return True

    print("FAIL")
    for f in failures[:10]:
        print(f)
    return False


if __name__ == "__main__":
    sys.exit(0 if run_checks() else 1)

from typing import List
from collections import deque
from itertools import combinations
import random


def _lcp(a: str, b: str) -> int:
    m = min(len(a), len(b))
    i = 0
    while i < m and a[i] == b[i]:
        i += 1
    return i


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        def sliding_min(arr: List[int], m: int) -> List[int]:
            if m <= 0:
                return [0] * len(arr)
            if m > len(arr):
                return []
            dq = deque()
            res = []
            for i, x in enumerate(arr):
                while dq and arr[dq[-1]] >= x:
                    dq.pop()
                dq.append(i)
                while dq and dq[0] <= i - m:
                    dq.popleft()
                if i >= m - 1:
                    res.append(arr[dq[0]])
            return res

        pairs = sorted((w, i) for i, w in enumerate(words))
        sw = [w for w, _ in pairs]
        pos = [0] * n
        for p, (_, idx) in enumerate(pairs):
            pos[idx] = p

        adj = [_lcp(sw[i], sw[i + 1]) for i in range(n - 1)]

        if k == 1:
            W1 = [len(w) for w in sw]
        else:
            W1 = sliding_min(adj, k - 1)
        W2 = sliding_min(adj, k)

        L1 = len(W1)
        pref = [0] * L1
        cur = 0
        for i, v in enumerate(W1):
            if v > cur:
                cur = v
            pref[i] = cur

        suff = [0] * L1
        cur = 0
        for i in range(L1 - 1, -1, -1):
            if W1[i] > cur:
                cur = W1[i]
            suff[i] = cur

        L2 = len(W2)
        ans_sorted = [0] * n
        dq = deque()

        for p in range(n):
            if p < L2:
                v = W2[p]
                while dq and W2[dq[-1]] <= v:
                    dq.pop()
                dq.append(p)

            low = p - k
            while dq and dq[0] < low:
                dq.popleft()

            best2 = W2[dq[0]] if dq else 0

            best1 = 0
            li = p - k
            if li >= 0:
                if li >= L1:
                    li = L1 - 1
                if li >= 0:
                    best1 = pref[li]

            ri = p + 1
            if ri < L1 and suff[ri] > best1:
                best1 = suff[ri]

            ans_sorted[p] = best1 if best1 > best2 else best2

        return [ans_sorted[p] for p in pos]


def _brute(words: List[str], k: int) -> List[int]:
    n = len(words)
    res = []
    for i in range(n):
        rem = words[:i] + words[i + 1:]
        if len(rem) < k:
            res.append(0)
            continue
        best = 0
        for comb in combinations(rem, k):
            v = len(comb[0])
            for x in comb[1:]:
                v = min(v, _lcp(comb[0], x))
                if v == 0:
                    break
            if v > best:
                best = v
        res.append(best)
    return res


if __name__ == "__main__":
    sol = Solution()

    assert sol.longestCommonPrefix(["jump", "run", "run", "jump", "run"], 2) == [3, 4, 4, 3, 4]
    assert sol.longestCommonPrefix(["dog", "racer", "car"], 2) == [0, 0, 0]
    assert sol.longestCommonPrefix(["a"], 1) == [0]
    assert sol.longestCommonPrefix(["a", "b"], 2) == [0, 0]
    assert sol.longestCommonPrefix(["a", "b"], 1) == [1, 1]
    assert sol.longestCommonPrefix(["a", "b", "c"], 1) == [1, 1, 1]
    assert sol.longestCommonPrefix(["a", "aa", "aaa"], 2) == [2, 1, 1]
    assert sol.longestCommonPrefix(["run", "run", "run"], 2) == [3, 3, 3]
    assert sol.longestCommonPrefix(["a", "ab", "abc", "abcd"], 2) == [3, 3, 2, 2]
    assert sol.longestCommonPrefix(["a", "aa", "aaa", "b"], 3) == [0, 0, 0, 1]

    random.seed(12345)
    for _ in range(500):
        n = random.randint(1, 8)
        k = random.randint(1, n)
        words = []
        for __ in range(n):
            L = random.randint(1, 4)
            words.append(''.join(random.choice('ab') for _ in range(L)))
        if n > 1 and random.random() < 0.5:
            a = random.randrange(n)
            b = random.randrange(n - 1)
            if b >= a:
                b += 1
            words[a] = words[b]

        expected = _brute(words, k)
        got = sol.longestCommonPrefix(words, k)
        assert got == expected, (words, k, expected, got)

    print("All tests passed")

import sys
from math import isqrt


def icbrt(n: int) -> int:
    if n <= 0:
        return 0
    lo = 0
    hi = 1 << ((n.bit_length() + 2) // 3)
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo


def main() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    limit = icbrt(N - 1)

    for d in range(1, limit + 1):
        if N % d != 0:
            continue

        m = N // d
        val = 3 * (4 * m - d * d)
        if val < 0:
            continue

        t = isqrt(val)
        if t * t != val:
            continue

        rem = t - 3 * d
        if rem > 0 and rem % 6 == 0:
            y = rem // 6
            print(y + d, y)
            return

    print(-1)


if __name__ == "__main__":
    main()

import sys
from collections import deque

sys.setrecursionlimit(1_000_000)


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]
        self.level = []
        self.it = []

    def add_edge(self, fr, to, cap):
        if fr == to:
            return
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def bfs(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        q = deque([s])
        g = self.g
        while q:
            v = q.popleft()
            for to, cap, rev in g[v]:
                if cap > 0 and level[to] < 0:
                    level[to] = level[v] + 1
                    q.append(to)
        self.level = level
        return level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        g = self.g
        level = self.level
        it = self.it
        while it[v] < len(g[v]):
            e = g[v][it[v]]
            if e[1] > 0 and level[v] + 1 == level[e[0]]:
                d = self.dfs(e[0], t, f if f < e[1] else e[1])
                if d:
                    e[1] -= d
                    g[e[0]][e[2]][1] += d
                    return d
            it[v] += 1
        return 0

    def max_flow(self, s, t, limit):
        flow = 0
        while flow < limit and self.bfs(s, t):
            self.it = [0] * self.n
            while flow < limit:
                f = self.dfs(s, t, limit - flow)
                if not f:
                    break
                flow += f
        return flow


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))

    edges = []
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        edges.append((u, v))

    def feasible(D):
        if D == 0:
            return True

        V = N * D
        s = V
        t = V + 1
        dinic = Dinic(V + 2)
        INF = K + 1

        def idx(v, i):
            return v * D + i

        for i in range(D):
            dinic.add_edge(s, idx(N - 1, i), INF)
            dinic.add_edge(idx(0, i), t, INF)

        for v in range(N):
            for i in range(1, D):
                dinic.add_edge(idx(v, i), idx(v, i - 1), INF)

        for u, v in edges:
            for i in range(D):
                dinic.add_edge(idx(v, i), idx(u, i), 1)
            for i in range(1, D):
                dinic.add_edge(idx(v, i), idx(u, i - 1), INF)

        return dinic.max_flow(s, t, K + 1) <= K

    low = 0
    high = min(K, N - 1)

    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1

    print(low)


