        solve()

from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        total = n * (n + 1) // 2
        m = len(conflictingPairs)
        if m == 0:
            return total

        by_r = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_r[b].append((a, idx))

        cnt = [0] * (n + 1)
        first_id = [-1] * (n + 1)
        gain = [0] * m

        top1 = 0
        top2 = 0
        bad = 0

        for r in range(1, n + 1):
            for l, idx in by_r[r]:
                cnt[l] += 1
                if cnt[l] == 1:
                    first_id[l] = idx

                if l > top1:
                    top2 = top1
                    top1 = l
                elif l < top1 and l > top2:
                    top2 = l

            bad += top1
            if top1 > 0 and cnt[top1] == 1:
                gain[first_id[top1]] += top1 - top2

        return total - bad + max(gain)

import sys
from math import comb

def fwht(a, n):
    h = 1
    while h < n:
        h2 = h << 1
        for i in range(0, n, h2):
            for j in range(i, i + h):
                x = a[j]
                y = a[j + h]
                a[j] = x + y
                a[j + h] = x - y
        h = h2

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    H = int(data[0])
    W = int(data[1])
    n = 1 << W
    cnt = [0] * n
    for s in data[2:2 + H]:
        cnt[int(s, 2)] += 1

    cost = [min(k, W - k) for k in range(W + 1)]
    G = [0] * (W + 1)
    for t in range(W + 1):
        total = 0
        wt = W - t
        for k, f in enumerate(cost):
            if f:
                s = 0
                lo = max(0, k - wt)
                hi = min(t, k)
                for j in range(lo, hi + 1):
                    term = comb(t, j) * comb(wt, k - j)
                    if j & 1:
                        s -= term
                    else:
                        s += term
                total += f * s
        G[t] = total

    fwht(cnt, n)
    g = G
    for i in range(n):
        cnt[i] *= g[i.bit_count()]
    fwht(cnt, n)
    print(min(cnt) // n)

