class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        pats = [ord(c) - 97 for c in str2]
        fixed = [-1] * L
        forbid = [0] * L

        range_m = range(m)
        range26 = range(26)

        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range_m:
                    pos = i + j
                    val = pats[j]
                    old = fixed[pos]
                    if old == -1:
                        fixed[pos] = val
                    elif old != val:
                        return ""
            else:
                forbid[i + m - 1] = 1

        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pats[i] != pats[j]:
                j = pi[j - 1]
            if pats[i] == pats[j]:
                j += 1
            pi[i] = j
        pi_full = pi[m - 1]

        trans = [[0] * 26 for _ in range(m)]
        for k in range_m:
            row = trans[k]
            pk = pats[k]
            if k == 0:
                for ci in range26:
                    row[ci] = 1 if ci == pk else 0
            else:
                fall = trans[pi[k - 1]]
                for ci in range26:
                    row[ci] = k + 1 if ci == pk else fall[ci]

        all_states = (1 << m) - 1
        bits = [1 << k for k in range_m]
        mode_items = [[None] * m for _ in range(54)]
        mode_all = [0] * 54

        for f in range(-1, 26):
            chars = range26 if f == -1 else (f,)
            for forb in (0, 1):
                mode = (f + 1) * 2 + forb
                items = mode_items[mode]
                for k in range_m:
                    mask = 0
                    trk = trans[k]
                    for ci in chars:
                        raw = trk[ci]
                        if raw == m:
                            if forb:
                                continue
                            mask |= 1 << pi_full
                        else:
                            mask |= 1 << raw
                    items[k] = (mask, bits[k])
                    if mask:
                        mode_all[mode] |= bits[k]

        feasible = [0] * (L + 1)
        feasible[L] = all_states

        for p in range(L - 1, -1, -1):
            mode = (fixed[p] + 1) * 2 + forbid[p]
            nxt = feasible[p + 1]
            if nxt == all_states:
                cur = mode_all[mode]
            else:
                cur = 0
                for mask, bit in mode_items[mode]:
                    if mask & nxt:
                        cur |= bit
            if cur == 0:
                return ""
            feasible[p] = cur

        if (feasible[0] & 1) == 0:
            return ""

        letters = [chr(97 + i) for i in range26]
        all_chars = range26
        single_chars = [(i,) for i in range26]
        res = []
        k = 0

        for p in range(L):
            f = fixed[p]
            forb = forbid[p]
            trk = trans[k]
            chars = all_chars if f == -1 else single_chars[f]
            for ci in chars:
                raw = trk[ci]
                if raw == m:
                    if forb:
                        continue
                    nk = pi_full
                else:
                    nk = raw
                if (feasible[p + 1] >> nk) & 1:
                    res.append(letters[ci])
                    k = nk
                    break
            else:
                return ""

        return ''.join(res)

from typing import List


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        if k <= 1:
            return 0

        # Not needed for the stated constraints (k >= 4), but keeps the method
        # correct for the trivial k == 2 case.
        if k == 2:
            if not points:
                return 0
            it = iter(points)
            x0, y0 = next(it)
            max_sum = min_sum = x0 + y0
            max_diff = min_diff = x0 - y0
            for x, y in it:
                s = x + y
                if s > max_sum:
                    max_sum = s
                elif s < min_sum:
                    min_sum = s

                d = x - y
                if d > max_diff:
                    max_diff = d
                elif d < min_diff:
                    min_diff = d

            return max(max_sum - min_sum, max_diff - min_diff)

        C = 4 * side

        # Perimeter coordinate in [0, 4*side).
        # The if-order assigns corners consistently:
        # (0,0) -> 0, (side,0) -> side, (side,side) -> 2*side, (0,side) -> 3*side.
        p = []
        for x, y in points:
            if y == 0:
                p.append(x)
            elif x == side:
                p.append(side + y)
            elif y == side:
                p.append(3 * side - x)
            else:  # x == 0
                p.append(4 * side - y)

        p.sort()
        n = len(p)
        if k > n:
            return 0

        p2 = p + [v + C for v in p]
        m = 2 * n

        def feasible(D: int) -> bool:
            if D == 0:
                return True

            # The k clockwise gaps around the perimeter sum to C.
            if k * D > C:
                return False

            # next[i] = first index j with p2[j] >= p2[i] + D.
            nxt = [0] * m
            j = 0
            p2_local = p2
            for i in range(m):
                if j < i:
                    j = i
                target = p2_local[i] + D
                while j < m and p2_local[j] < target:
                    j += 1
                nxt[i] = j

            need = k - 1
            wrap = C - D
            jump_range = range(need)
            p_local = p
            nxt_local = nxt

            for i in range(n):
                cur = i
                limit = i + n

                for _ in jump_range:
                    cur = nxt_local[cur]
                    if cur >= limit:
                        break
                else:
                    # Wrap gap from cur back to i + C is at least D.
                    if p2_local[cur] <= p_local[i] + wrap:
                        return True

            return False

        # For k >= 4, the answer is at most side.
        lo, hi = 0, side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo


def _run_tests() -> None:
    from itertools import combinations
    import random

    def boundary_points(side: int):
        pts = []
        for x in range(side + 1):
            pts.append((x, 0))
        for y in range(1, side + 1):
            pts.append((side, y))
        for x in range(side - 1, -1, -1):
            pts.append((x, side))
        for y in range(side - 1, 0, -1):
            pts.append((0, y))
        return pts

    def brute_force(points, k: int) -> int:
        best = 0
        for comb in combinations(points, k):
            mn = 10**18
            for i in range(k):
                x1, y1 = comb[i]
                for j in range(i + 1, k):
                    x2, y2 = comb[j]
                    d = abs(x1 - x2) + abs(y1 - y2)
                    if d < mn:
                        mn = d
            if mn > best:
                best = mn
        return best

    sol = Solution()

    # Provided examples.
    assert sol.maxDistance(2, [[0, 2], [2, 0], [2, 2], [0, 0]], 4) == 2
    assert sol.maxDistance(2, [[0, 0], [1, 2], [2, 0], [2, 2], [2, 1]], 4) == 1
    assert sol.maxDistance(
        2,
        [[0, 0], [0, 1], [0, 2], [1, 2], [2, 0], [2, 2], [2, 1]],
        5,
    ) == 1

    # Random brute-force validation on small squares.
    random.seed(2024)
    for _ in range(200):
        side = random.randint(1, 4)
        all_pts = boundary_points(side)
        n = random.randint(4, min(len(all_pts), 10))
        pts = random.sample(all_pts, n)
        k = random.randint(4, min(n, 6))

        expected = brute_force(pts, k)
        got = sol.maxDistance(side, pts, k)

        if expected != got:
            print("Mismatch:", side, pts, k, "expected", expected, "got", got)
            raise AssertionError("Random validation failed")


if __name__ == "__main__":
    _run_tests()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    adj = [[] for _ in range(n)]
    idx = 1
    for _ in range(n - 1):
        a = int(data[idx]) - 1
        b = int(data[idx + 1]) - 1
        idx += 2
        adj[a].append(b)
        adj[b].append(a)
    del data

    parent = [-1] * n
    parent[0] = 0
    order = [0]
    i = 0
    while i < len(order):
        v = order[i]
        i += 1
        pv = parent[v]
        for to in adj[v]:
            if to == pv:
                continue
            if parent[to] != -1:
                continue
            parent[to] = v
            order.append(to)

    dp = [0] * n
    max_core = 0

    for v in reversed(order):
        if len(adj[v]) < 4:
            continue
        t0 = t1 = t2 = t3 = 0
        for to in adj[v]:
            if parent[to] == v:
                val = dp[to]
                if val > t0:
                    t3 = t2
                    t2 = t1
                    t1 = t0
                    t0 = val
                elif val > t1:
                    t3 = t2
                    t2 = t1
                    t1 = val
                elif val > t2:
                    t3 = t2
                    t2 = val
                elif val > t3:
                    t3 = val
        dp[v] = 1 + t0 + t1 + t2
        best = 1 + t0 + t1 + t2 + t3
        if best > max_core:
            max_core = best

    if max_core == 0:
        print(-1)
    else:
        print(3 * max_core + 2)

