from bisect import bisect_left, bisect_right


class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')

        # Only the pattern "**" can match the empty substring.
        if not A and not B and not C:
            return 0

        n = len(s)
        lenA, lenB, lenC = len(A), len(B), len(C)

        def find_occurrences(pat: str):
            """Return all start positions of pat in s using KMP."""
            m = len(pat)
            if m == 0 or m > n:
                return []

            # Prefix function for KMP.
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            occ = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    occ.append(i - m + 1)
                    j = pi[j - 1]
            return occ

        A_occ = find_occurrences(A) if A else []
        B_occ = find_occurrences(B) if B else []
        C_occ = find_occurrences(C) if C else []

        INF = 10**18
        ans = INF

        # Case 1: middle literal block B is non-empty.
        if B:
            if A and not A_occ:
                return -1
            if C and not C_occ:
                return -1
            if not B_occ:
                return -1

            for b in B_occ:
                # Choose the latest A occurrence ending before B starts.
                if A:
                    ia = bisect_right(A_occ, b - lenA) - 1
                    if ia < 0:
                        continue
                    start = A_occ[ia]
                else:
                    start = b

                # Choose the earliest C occurrence starting after B ends.
                if C:
                    ic = bisect_left(C_occ, b + lenB)
                    if ic == len(C_occ):
                        # Later B starts only need even later C starts.
                        break
                    end = C_occ[ic] + lenC - 1
                else:
                    end = b + lenB - 1

                cur = end - start + 1
                if cur < ans:
                    ans = cur

            return -1 if ans == INF else ans

        # Case 2: B is empty, so the pattern is effectively A * C.
        if not A:
            return lenC if C_occ else -1
        if not C:
            return lenA if A_occ else -1
        if not A_occ or not C_occ:
            return -1

        for a in A_occ:
            # Earliest C occurrence that does not overlap A.
            ic = bisect_left(C_occ, a + lenA)
            if ic == len(C_occ):
                # Later A starts only need even later C starts.
                break
            end = C_occ[ic] + lenC - 1
            cur = end - a + 1
            if cur < ans:
                ans = cur

        return -1 if ans == INF else ans

import sys
from math import gcd, isqrt
from itertools import islice

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    K = int(data[1])
    A = list(map(int, islice(data, 2, None)))
    del data

    w = sys.stdout.write
    CHUNK = 100000

    if K == 1:
        for i in range(0, N, CHUNK):
            w('\n'.join(map(str, A[i:i + CHUNK])) + '\n')
        return

    if K == N:
        g = 0
        for x in A:
            g = gcd(g, x)
        w((str(g) + '\n') * N)
        return

    M = max(A)
    f = [0] * (M + 1)
    for x in A:
        f[x] += 1

    is_prime = bytearray(b'\x01') * (M + 1)
    is_prime[0:2] = b'\x00\x00'
    for i in range(2, isqrt(M) + 1):
        if is_prime[i]:
            start = i * i
            is_prime[start:M + 1:i] = b'\x00' * (((M - start) // i) + 1)

    primes = [i for i in range(2, M + 1) if is_prime[i]]
    del is_prime

    for p in primes:
        for i in range(M // p, 0, -1):
            f[i] += f[i * p]

    for d in range(1, M + 1):
        f[d] = d if f[d] >= K else 0

    for p in primes:
        for i in range(1, M // p + 1):
            v = f[i]
            if v and v > f[i * p]:
                f[i * p] = v

    for i in range(0, N, CHUNK):
        w('\n'.join([str(f[x]) for x in A[i:i + CHUNK]]) + '\n')

if __name__ == '__main__':
    main()

import sys


def min_swaps(s: str) -> int:
    adjusted = []
    ones = 0
    for i, ch in enumerate(s):
        if ch == '1':
            adjusted.append(i - ones)
            ones += 1

    if not adjusted:
        return 0

    med = adjusted[len(adjusted) // 2]

    # The median is always feasible, but clamping is harmless.
    n = len(s)
    k = len(adjusted)
    if med < 0:
        med = 0
    elif med > n - k:
        med = n - k

    total = 0
    for x in adjusted:
        total += abs(x - med)
    return total


def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    s = data[1] if len(data) >= 2 else data[0]
    print(min_swaps(s))


def brute_min_swaps(s: str) -> int:
    from collections import deque

    n = len(s)
    k = s.count('1')

    targets = set()
    for l in range(n - k + 1):
        targets.add('0' * l + '1' * k + '0' * (n - k - l))

    q = deque([(s, 0)])
    seen = {s}

    while q:
        state, d = q.popleft()
        if state in targets:
            return d

        for i in range(n - 1):
            if state[i] != state[i + 1]:
                lst = list(state)
                lst[i], lst[i + 1] = lst[i + 1], lst[i]
                ns = ''.join(lst)
                if ns not in seen:
                    seen.add(ns)
                    q.append((ns, d + 1))

    return -1


def selftest() -> None:
    samples = [
        (7, '0101001'),
        (3, '100'),
        (10, '0101001001'),
    ]

    for n, s in samples:
        if len(s) != n:
            raise AssertionError('bad sample length')
        if min_swaps(s) != brute_min_swaps(s):
            raise AssertionError(f'sample mismatch: {n} {s}')

    for n in range(2, 11):
        for i in range(n):
            s = '0' * i + '1' + '0' * (n - i - 1)
            if min_swaps(s) != 0:
                raise AssertionError(f'single one mismatch: {s}')

        s = '1' * n
        if min_swaps(s) != 0:
            raise AssertionError(f'all ones mismatch: {s}')

        for phase in (0, 1):
            s = ''.join('1' if (j - phase) % 2 == 0 else '0' for j in range(n))
            if '1' in s and min_swaps(s) != brute_min_swaps(s):
                raise AssertionError(f'alternating mismatch: {s}')

    import random
    rng = random.Random(0)
    for _ in range(200):
        n = rng.randint(2, 8)
        s = ''.join(rng.choice('01') for _ in range(n))
        if '1' in s and min_swaps(s) != brute_min_swaps(s):
            raise AssertionError(f'random mismatch: {s}')

    print('selftest ok')


if __name__ == '__main__':
    if len(sys.argv) > 1 and sys.argv[1] == '--selftest':
        selftest()
    else:
        solve()

