import sys
from collections import deque

INF = 10**18


def compute_answer(N, adj, S, T):
    # BFS from S: shortest distance d and one shortest S-T path P.
    dist = [-1] * N
    parent = [-1] * N
    dq = deque([S])
    dist[S] = 0
    while dq:
        u = dq.popleft()
        nd = dist[u] + 1
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = nd
                parent[v] = u
                dq.append(v)

    d = dist[T]

    inP = [False] * N
    cur = T
    while True:
        inP[cur] = True
        if cur == S:
            break
        cur = parent[cur]

    # E1: minimum excess of an S-T walk that uses an off-P vertex
    # and does not visit the opposite endpoint early.
    def bfs_banned(start, banned):
        dist = [-1] * N
        dist[start] = 0
        dq = deque([start])
        while dq:
            u = dq.popleft()
            nd = dist[u] + 1
            for v in adj[u]:
                if v == banned or dist[v] != -1:
                    continue
                dist[v] = nd
                dq.append(v)
        return dist

    dist1 = bfs_banned(S, T)
    dist2 = bfs_banned(T, S)

    best = INF
    for v in range(N):
        if not inP[v]:
            a = dist1[v]
            b = dist2[v]
            if a != -1 and b != -1:
                s = a + b
                if s < best:
                    best = s

    e1 = best - d if best != INF else INF
    if e1 < 0:
        e1 = 0

    # If there is another shortest S-T path, the lower bound is attainable.
    if e1 == 0:
        return 2 * d

    # E2: endpoint buffer/branch rule.
    # For endpoint e, BFS in the graph where all P-vertices except e are banned.
    # If a reached vertex x has at least two BFS children, it can serve as a
    # passing gadget at distance r = dist[x], with excess 4*r + 4.
    e2 = INF
    for e in (S, T):
        distE = [-1] * N
        distE[e] = 0
        dq = deque([e])
        while dq:
            u = dq.popleft()
            nd = distE[u] + 1
            for v in adj[u]:
                if inP[v] and v != e:
                    continue
                if distE[v] == -1:
                    distE[v] = nd
                    dq.append(v)

        for u in range(N):
            du = distE[u]
            if du == -1:
                continue
            cnt = 0
            for v in adj[u]:
                if inP[v] and v != e:
                    continue
                if distE[v] == du + 1:
                    cnt += 1
                    if cnt >= 2:
                        break
            if cnt >= 2:
                val = 4 * du + 4
                if val < e2:
                    e2 = val
                    if e2 == 4:
                        break

        if e2 == 4:
            break

    excess = e1 if e1 < e2 else e2
    if excess >= INF:
        return -1
    return 2 * d + excess


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M, S, T = data[0], data[1], data[2] - 1, data[3] - 1
    adj = [[] for _ in range(N)]
    idx = 4
    for _ in range(M):
        u = data[idx] - 1
        v = data[idx + 1] - 1
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    print(compute_answer(N, adj, S, T))


