def is_connected(N, adj):
    seen = [False] * N
    seen[0] = True
    dq = deque([0])
    while dq:
        u = dq.popleft()
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                dq.append(v)
    return all(seen)


def build_trans(N, adj):
    trans = [[] for _ in range(N * N)]
    for a in range(N):
        for b in range(N):
            if a == b:
                continue
            st = a * N + b
            for na in adj[a]:
                if na != b:
                    trans[st].append(na * N + b)
            for nb in adj[b]:
                if nb != a:
                    trans[st].append(a * N + nb)
    return trans


def exact_bfs(trans, start, goal):
    n = len(trans)
    dist = [-1] * n
    dq = deque([start])
    dist[start] = 0
    while dq:
        st = dq.popleft()
        if st == goal:
            return dist[st]
        nd = dist[st] + 1
        for ns in trans[st]:
            if dist[ns] == -1:
                dist[ns] = nd
                dq.append(ns)
    return -1


def stress():
    # All connected simple graphs up to N=6, all S,T pairs.
    for N in range(2, 7):
        edge_list = [(i, j) for i in range(N) for j in range(i + 1, N)]
        E = len(edge_list)
        pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

        for mask in range(1 << E):
            adj = [[] for _ in range(N)]
            for idx, (u, v) in enumerate(edge_list):
